const fs = require('fs');
const readline = require('readline');

const MOD = 1000000007n;

async function main() {
  const rl = readline.createInterface({
    input: fs.createReadStream('data.txt', { highWaterMark: 1 << 16 }),
    crlfDelay: Infinity,
  });

  let count = 0;
  let sum = 0n;
  let max = 0;

  for await (const line of rl) {
    const s = line.trim();
    if (s === '') continue;
    count++;
    const v = BigInt(s);
    sum += v;
    if (sum >= MOD * 1000000n) sum %= MOD;
    const n = Number(v);
    if (n > max) max = n;
  }
  sum %= MOD;

  console.log(JSON.stringify({ count, sum: Number(sum), max }));
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
